import ast
import numpy as np
from keras.src import backend
from keras.src.optimizers.adam import Adam

file_path = '/testbed/qa_instances_eval/Keras/optimizers_adam_amsgrad_vhat_monotonic_invariant/files/keras/src/test/optimizers/adam_amsgrad_vhat_monotonic_invariant_test.py'

with open(file_path, 'r', encoding='utf-8') as f:
    tree = ast.parse(f.read(), filename=file_path)

cases = []
for node in tree.body:
    if isinstance(node, ast.ClassDef) and node.name == 'AdamAmsgradVhatMonotonicInvariantQATest':
        for fn in node.body:
            if isinstance(fn, ast.FunctionDef) and fn.name.startswith('test_case_'):
                # find v1, v2 = self._run_scenario(...)
                for stmt in fn.body:
                    if isinstance(stmt, ast.Assign) and isinstance(stmt.value, ast.Call):
                        call = stmt.value
                        if isinstance(call.func, ast.Attribute) and call.func.attr == '_run_scenario':
                            vals = [ast.literal_eval(arg) for arg in call.args]
                            lr, b1, b2, eps, grad_steps = vals
                            cases.append((fn.name, lr, b1, b2, eps, grad_steps))
                            break

cases.sort(key=lambda x: x[0])

all_ok = True
violations = []
for name, lr, b1, b2, eps, grad_steps in cases:
    optimizer = Adam(learning_rate=lr, beta_1=b1, beta_2=b2, epsilon=eps, amsgrad=True)
    v1 = backend.Variable(np.array([1.0, -0.5, 0.3], dtype='float32'), name='adam_t_v1')
    v2 = backend.Variable(np.array([-0.2, 0.7, -1.1], dtype='float32'), name='adam_t_v2')

    histories = None
    for g1, g2 in grad_steps:
        optimizer.apply([np.array(g1, dtype='float32'), np.array(g2, dtype='float32')], [v1, v2])
        if histories is None:
            histories = {vh.path: [] for vh in optimizer._velocity_hats}
        for vh in optimizer._velocity_hats:
            histories[vh.path].append(np.array(vh.numpy(), dtype=np.float64))

    tol = 1e-9
    for path, seq in histories.items():
        for i in range(1, len(seq)):
            delta = seq[i] - seq[i-1]
            if np.any(delta < -tol):
                all_ok = False
                violations.append((name, path, i, delta.tolist(), seq[i-1].tolist(), seq[i].tolist()))

print('cases', len(cases))
print('all_ok', all_ok)
print('violations', len(violations))
if violations:
    print('first_violation', violations[0])
PY

